    section9Body: 'মেনোপজ-পূর্ব পর্যায়ে হরমোনের মাত্রা একদিন থেকে পরের দিন উল্লেখযোগ্যভাবে বদলাতে পারে। তাই একটিমাত্র পরীক্ষা সবসময় পরিস্থিতির পূর্ণ চিত্র দেয় না।',
