    section3Body2: 'Ин нишонаҳо метавонанд якчанд сабаб дошта бошанд: онҳо на ҳамеша бо гормонҳо алоқаманданд ва шиддати онҳо аз шахс ба шахс хеле гуногун аст.',
    section4Body: 'Прогестерон танҳо пас аз овуляция тавлид мешавад. Аммо дар перименопауза худи овуляция номунтазамтар мешавад — ки тавлиди онро камтар пешгӯишаванда мекунад.',
    section4Body2: 'Ин номунтазамӣ қисман тағйироти дар давра мушоҳидашударо шарҳ медиҳад: дарозии тағйирёбанда, ҳайзи баъзан зиёдтар ё камтар аз пештара.',
    section5Body: 'Ғайр аз тағйироти гормонӣ, якчанд омили дигар низ нақш доранд: сифати хоб, сатҳи стресс, тарзи зиндагӣ ва фарқиятҳои хоси ҳар шахс.',
