    section4Body: 'Progesteron hanya dihasilkan selepas ovulasi. Tetapi semasa perimenopaus, ovulasi itu sendiri menjadi lebih tidak teratur — yang menjadikan penghasilannya kurang boleh diramal.',
    section4Body2: 'Ketidakteraturan ini sebahagiannya menjelaskan perubahan yang dilihat pada kitaran: tempoh yang berubah-ubah, haid yang kadangkala lebih banyak atau lebih ringan berbanding sebelumnya.',
    section5Body: 'Selain perubahan hormon, beberapa faktor lain turut memainkan peranan: kualiti tidur, tahap tekanan, gaya hidup dan perbezaan yang khusus bagi setiap orang.',
