    infoCard2Text: 'Bilik tidur yang sejuk, pakaian yang ringan dan rutin waktu tidur yang stabil boleh membantu mengehadkan terjaga ini.',
    section8Body: 'Perubahan hormon boleh bertepatan dengan perubahan emosi, tanpa menjadi satu-satunya penjelasan: tidur, tekanan, perubahan hidup dan simptom fizikal juga memainkan peranan.',
    infoCard3Title: 'Untuk menenangkan anda',
