    section9Body: 'Tahap hormon boleh berubah dengan ketara dari satu hari ke hari berikutnya semasa perimenopaus. Oleh itu, satu ujian tidak sentiasa memberikan gambaran lengkap tentang keadaan.',
    infoCard4Title: 'Perlu diingat',
    infoCard4Text: 'Penilaian perubatan bergantung terutamanya pada umur, simptom dan sejarah kitaran anda — bukan hanya satu nombor.',
