    section2Body: 'Ukun-sidayaashu tartiib ayay u jawaabaan si aan joogto ahayn calaamadaha hormoonka ee ay soo dirto maskaxdu. Tani waa waxa wareegyada ka dhigaya kuwo aan joogto ahayn wuxuuna sharxayaa sababta astaamuhu u isbeddeli karaan bil ilaa bil.',
