    section6Caption: 'Orodha hii ni kwa taarifa tu: si utambuzi wa ugonjwa. Kila mtu hupitia mchanganyiko tofauti wa mabadiliko haya.',
    section7Body: 'Kutokwa jasho usiku kunaweza kukatiza usingizi, na kusababisha uchovu na ugumu wa kuzingatia siku inayofuata — mtindo unaojulikana katika kipindi hiki.',
    infoCard2Title: 'Kidokezo cha vitendo',
    infoCard2Text: 'Chumba cha kulala chenye ubaridi, nguo nyepesi, na utaratibu thabiti wa wakati wa kulala vinaweza kusaidia kupunguza kuamka huku.',
    section8Body: 'Mabadiliko ya homoni yanaweza sanjari na mabadiliko ya hali ya moyo, bila kuwa maelezo pekee: usingizi, msongo wa mawazo, mabadiliko ya maisha, na dalili za mwili pia vina nafasi.',
    infoCard3Title: 'Kukutuliza',
    infoCard3Text: 'Kuhisi hisia kali zaidi katika kipindi hiki hakumaanishi kuna tatizo: ni uzoefu wa kawaida unaoweza kuwa na sababu kadhaa kwa wakati mmoja.',
    section9Body: 'Viwango vya homoni vinaweza kutofautiana sana kutoka siku moja hadi nyingine wakati wa kukaribia kukoma hedhi. Kipimo kimoja kwa hiyo hakitoi picha kamili ya hali kila mara.',
    infoCard4Title: 'Inafaa kukumbuka',
    infoCard4Text: 'Tathmini ya kitabibu inategemea hasa umri wako, dalili zako, na historia ya mzunguko wako — si nambari moja tu.',
    section10Body: 'Kuandika unachopitia mwezi baada ya mwezi kunakusaidia kutambua mitindo yako mwenyewe badala ya kujilinganisha na wengine:',
