    infoCard1Text: 'Hindi pantay na bumababa ang antas ng hormone sa panahon ng perimenopause: maaari silang magbago-bago, tumaas at bumaba, bago manatili sa mas mababang antas pagkatapos ng menopause.',
    section2Body: 'Unti-unting hindi na gaanong regular ang pagtugon ng mga obaryo sa mga hormonal na hudyat mula sa utak. Ito ang nagiging sanhi ng hindi regular na mga siklo at nagpapaliwanag kung bakit maaaring magbago ang mga sintomas buwan-buwan.',
    tip1Title: 'Mabuting malaman',
    tip1Text: 'Lubos na posibleng magkaroon ng kapansin-pansing mga sintomas sa isang buwan, pagkatapos ay halos wala sa susunod. Hindi ito abnormal: sumasalamin lamang ito sa mga hormonal na pagbabago-bago ng panahong ito.',
    section3Body: 'Ang mga pagbabago sa estrogen ay maaaring may kaugnayan sa ilang pagbabago:',
