    section3Body2: 'Maaaring may iba’t ibang sanhi ang mga sintomas na ito: hindi laging may kaugnayan ang mga ito sa hormone, at lubhang nag-iiba ang tindi sa bawat tao.',
    section4Body: 'Ang progesterone ay ginagawa lamang pagkatapos ng obulasyon. Ngunit sa perimenopause, mismong ang obulasyon ay nagiging mas hindi regular — kaya mas hindi mahulaan ang produksyon nito.',
    section4Body2: 'Bahagyang ipinapaliwanag ng iregularidad na ito ang mga pagbabagong nakikita sa siklo: nag-iiba-ibang haba, mga regla na minsan ay mas marami o mas kaunti kaysa dati.',
    section5Body: 'Bukod sa mga hormonal na pagbabago-bago, may iba pang salik na gumaganap: kalidad ng tulog, antas ng stress, pamumuhay, at mga pagkakaibang partikular sa bawat tao.',
