    section6Caption: 'Para sa impormasyon lamang ang listahang ito: hindi ito diagnosis. Bawat tao ay nakararanas ng ibang kombinasyon ng mga pagbabagong ito.',
    section7Body: 'Maaaring maputol ng pagpapawis sa gabi ang tulog, na nagdudulot ng pagod at hirap sa konsentrasyon kinabukasan — isang pattern na karaniwan sa panahong ito.',
    infoCard2Title: 'Praktikal na payo',
    infoCard2Text: 'Ang malamig na kuwarto, magaang damit, at matatag na gawi sa oras ng pagtulog ay makakatulong na limitahan ang mga paggising na ito.',
    section8Body: 'Ang mga hormonal na pagbabago-bago ay maaaring kasabay ng mga pagbabago sa mood, nang hindi ito ang tanging paliwanag: may papel din ang tulog, stress, mga pagbabago sa buhay, at mga pisikal na sintomas.',
    infoCard3Title: 'Para mapanatag ka',
    infoCard3Text: 'Ang pagiging mas emosyonal sa panahong ito ay hindi nangangahulugang may mali: karaniwang karanasan ito na maaaring may ilang sanhi nang sabay-sabay.',
    section9Body: 'Maaaring malaki ang pagkakaiba ng antas ng hormone mula sa isang araw hanggang sa susunod sa panahon ng perimenopause. Kaya ang iisang test ay hindi laging nagbibigay ng kumpletong larawan ng sitwasyon.',
    infoCard4Title: 'Dapat isaisip',
