    section2Body: 'ਅੰਡਕੋਸ਼ ਹੌਲੀ-ਹੌਲੀ ਦਿਮਾਗ਼ ਵੱਲੋਂ ਭੇਜੇ ਹਾਰਮੋਨ ਸੰਕੇਤਾਂ ਪ੍ਰਤੀ ਘੱਟ ਨਿਯਮਿਤ ਢੰਗ ਨਾਲ ਪ੍ਰਤੀਕਿਰਿਆ ਦਿੰਦੇ ਹਨ। ਇਹੀ ਚੱਕਰਾਂ ਨੂੰ ਅਨਿਯਮਿਤ ਬਣਾਉਂਦਾ ਹੈ ਅਤੇ ਦੱਸਦਾ ਹੈ ਕਿ ਲੱਛਣ ਮਹੀਨੇ ਤੋਂ ਮਹੀਨੇ ਕਿਉਂ ਬਦਲ ਸਕਦੇ ਹਨ।',
